const fs = require('node:fs');
const path = require('node:path');

function normalizeGeneratedTypes(source) {
	return source
		.replace(
			/^\/\/ Generated by Wrangler by running `[^`\r\n]+` \(hash: ([0-9a-f]+)\)$/mu,
			'// Generated by Wrangler (configuration hash: $1)',
		)
		.replace(/[ \t]+$/gmu, '');
}

function withTemporaryDirectory(parent, callback) {
	const temporaryDirectory = fs.mkdtempSync(path.join(parent, 'tcl-cloudflare-types-'));
	try {
		return callback(temporaryDirectory);
	} finally {
		fs.rmSync(temporaryDirectory, { recursive: true, force: true });
	}
}

module.exports = { normalizeGeneratedTypes, withTemporaryDirectory };
